import { Markdown } from '../document/Markdown.tsx'
import type { RunInputs, RunScope } from './api.ts'
import { AppLink, ErrorPanel, LoadingPanel } from './panels.tsx'
import { runPathname } from './routes.ts'
import { deadlinesLabel, formatDuration, shortRevision } from './status.ts'
import type { Resource } from './useResource.ts'

type Props = {
  scope: RunScope
  inputs: Resource<RunInputs | null>
  onRetry: () => void
  onNavigate: (pathname: string) => void
  panelId: string
  tabId: string
}

export const INPUTS_NONE_SENTENCE = 'Inputs not recorded for this run (the export predates run inputs; re-export it with the workflow CLI).'

/** The Assignment tab: what the run was asked to do, pinned from its own files, with each worker's task rendered as Markdown. */
export function AssignmentPanel({ scope, inputs, onRetry, onNavigate, panelId, tabId }: Props) {
  let content: React.ReactNode
  if (inputs.status === 'loading' || inputs.status === 'idle') content = <LoadingPanel>Loading the run inputs…</LoadingPanel>
  else if (inputs.status === 'error') content = <ErrorPanel error={inputs.error} what="The run inputs" onRetry={onRetry} />
  else if (inputs.data === null) content = <p className="projects-muted" data-testid="assignment-inputs-none">{INPUTS_NONE_SENTENCE}</p>
  else {
    const data = inputs.data
    content = (
      <>
        <dl className="projects-facts">
          <div><dt>Feature</dt><dd>{data.feature}</dd></div>
          <div><dt>Source branch</dt><dd>{data.source_branch === null ? 'None recorded' : <code>{data.source_branch}</code>}</dd></div>
          <div><dt>Base commit</dt><dd><code title={data.base_commit}>{shortRevision(data.base_commit)}</code></dd></div>
          <div><dt>Mode</dt><dd>{data.mode}</dd></div>
          {data.automatic && (
            <>
              <div><dt>Deadlines</dt><dd>{deadlinesLabel(data.automatic)}</dd></div>
              <div><dt>Permission mode</dt><dd><code>{data.automatic.permission_mode}</code></dd></div>
              <div><dt>Finish</dt><dd>{data.automatic.finish}</dd></div>
              <div><dt>Reviewer transport</dt><dd data-testid="assignment-reviewer-transport">{data.automatic.reviewer_transport ?? <span className="projects-muted">not pinned (the run predates the setting)</span>}</dd></div>
            </>
          )}
          <div><dt>Attempt cap</dt><dd>{data.max_verification_attempts} per lane and phase</dd></div>
        </dl>

        <h4 id="assignment-setup-title">Setup commands</h4>
        {data.setup.length === 0 ? (
          <p className="projects-muted" data-testid="assignment-setup">No setup commands were pinned.</p>
        ) : (
          <ul className="evidence-list" data-testid="assignment-setup" aria-labelledby="assignment-setup-title">
            {data.setup.map((step, index) => (
              <li key={index}><code>{step.command}</code> <span className="projects-muted">· timeout {formatDuration(step.timeout_seconds)}</span></li>
            ))}
          </ul>
        )}

        {data.workers.map(worker => (
          <section key={worker.node_id} className="assignment-worker" data-testid="assignment-worker" data-worker={worker.node_id} aria-labelledby={`assignment-worker-${worker.node_id}`}>
            <h4 id={`assignment-worker-${worker.node_id}`}>
              Worker {worker.node_id} ({worker.role}) · launched by{' '}
              <AppLink href={runPathname(scope.projectId, scope.workflowId, scope.runId, worker.launch_node_id)} onNavigate={onNavigate}>{worker.launch_node_id}</AppLink>
            </h4>
            <div className="task-rendered" data-testid="assignment-task"><Markdown content={worker.task.text} /></div>
            {worker.task.truncated && <p className="projects-notice" role="note">The task text was truncated by the viewer API; the marker at its end says how many characters were left out.</p>}
            <h5 id={`assignment-owned-${worker.node_id}`}>Owned paths</h5>
            {worker.owned_paths.length === 0 ? <p className="projects-muted">No owned paths were pinned.</p> : (
              <ul className="evidence-list evidence-files" aria-labelledby={`assignment-owned-${worker.node_id}`}>
                {worker.owned_paths.map(path => <li key={path}><code>{path}</code></li>)}
              </ul>
            )}
            <h5 id={`assignment-checks-${worker.node_id}`}>Required checks</h5>
            {worker.checks.length === 0 ? <p className="projects-muted">No checks were required.</p> : (
              <ul className="evidence-list" aria-labelledby={`assignment-checks-${worker.node_id}`}>
                {worker.checks.map(check => (
                  <li key={check.id}>
                    <code>{check.command}</code>
                    <span className="projects-muted"> · {check.id} · {check.kind} · timeout {formatDuration(check.timeout_seconds)}</span>
                    {check.scenarios.length > 0 && (
                      <ul className="evidence-list assignment-scenarios">
                        {check.scenarios.map(scenario => <li key={scenario.id}><code>{scenario.id}</code> — {scenario.description}</li>)}
                      </ul>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </section>
        ))}
      </>
    )
  }
  return (
    <section role="tabpanel" id={panelId} aria-labelledby={tabId} className="assignment" data-testid="assignment">
      <h3>Assignment</h3>
      <p className="projects-muted">What this run was asked to do, pinned from its own plan, policy and receipts. Nothing here can be changed from the viewer.</p>
      {content}
    </section>
  )
}
import { useEffect, useRef, useState, type MouseEvent } from 'react'
import { Markdown } from '../document/Markdown.tsx'
import type { RunInputWorker, WorkerResult } from './api.ts'
import { formatDuration, formatTime } from './status.ts'
import type { Resource } from './useResource.ts'

type TaskProps = {
  worker: RunInputWorker
  /** The node's published result, when it loaded: required checks are matched to executed checks by exact command. */
  result: Resource<WorkerResult>
  /** A requirement quote to highlight in the task source, handed over by a finding link; null otherwise. */
  highlight: string | null
  /** Called once the highlight has been applied, so the run view forgets it (leaving the node drops it anyway). */
  onHighlightApplied: () => void
}

/** Scrolls to and focuses an executed check in the evidence list without touching the history. */
function jumpToCheck(event: MouseEvent<HTMLAnchorElement>, id: string) {
  const target = document.getElementById(id)
  if (!target) return
  event.preventDefault()
  target.scrollIntoView({ block: 'center' })
  target.focus()
}

/**
 * The pinned task of a worker: rendered Markdown or the exact source, the ownership boundary and the
 * required checks. When a finding link hands over a quote, the panel opens on the source with the quote
 * marked and scrolled into view. The quote is captured when the panel mounts (the node detail remounts per
 * node), so clearing the pending hand-off afterwards does not remove the mark until the reader leaves.
 */
export function TaskPanel({ worker, result, highlight, onHighlightApplied }: TaskProps) {
  const [view, setView] = useState<'rendered' | 'source'>(() => (highlight === null ? 'rendered' : 'source'))
  const [activeQuote] = useState(() => highlight)
  const markRef = useRef<HTMLElement>(null)
  useEffect(() => {
    if (activeQuote === null) return
    markRef.current?.scrollIntoView({ block: 'center' })
    onHighlightApplied()
  }, [activeQuote, onHighlightApplied])

  const text = worker.task.text
  const index = activeQuote === null ? -1 : text.indexOf(activeQuote)
  const executed = result.status === 'ready' ? result.data.checks : null

  return (
    <section className="evidence-section task-panel" aria-labelledby="task-title" data-testid="task-panel">
      <div className="task-head">
        <h4 id="task-title">Task</h4>
        <div role="group" aria-label="Task view" className="task-toggle">
          <button type="button" className="button button-small" aria-pressed={view === 'rendered'} onClick={() => setView('rendered')}>Rendered</button>
          <button type="button" className="button button-small" aria-pressed={view === 'source'} onClick={() => setView('source')}>Source</button>
        </div>
      </div>
      <p className="projects-muted">The assignment pinned in the run plan: the authored task plus the appended ownership and checks.</p>
      {worker.task.truncated && (
        <p className="projects-notice" role="note" data-testid="task-truncated">The task text was truncated by the viewer API; the marker at its end says how many characters were left out.</p>
      )}
      {activeQuote !== null && index === -1 && (
        <p className="projects-muted" data-testid="task-highlight-missing">The quoted requirement was not found in this task text, so nothing is highlighted.</p>
      )}
      {view === 'rendered' ? (
        <div className="task-rendered"><Markdown content={text} /></div>
      ) : (
        <pre className="task-source" data-testid="task-source" tabIndex={0}>
          {index === -1 ? text : (
            <>
              {text.slice(0, index)}
              <mark ref={markRef} className="task-highlight" data-testid="task-highlight">{activeQuote}</mark>
              {text.slice(index + activeQuote!.length)}
            </>
          )}
        </pre>
      )}

      <h5 id="task-owned-title">Owned paths</h5>
      {worker.owned_paths.length === 0 ? (
        <p className="projects-muted">No owned paths were pinned.</p>
      ) : (
        <ul className="evidence-list evidence-files" data-testid="task-owned-paths" aria-labelledby="task-owned-title">
          {worker.owned_paths.map(path => <li key={path}><code>{path}</code></li>)}
        </ul>
      )}

      <h5 id="task-checks-title">Required checks</h5>
      {worker.checks.length === 0 ? (
        <p className="projects-muted">No checks were required.</p>
      ) : (
        <ul className="evidence-list task-checks" data-testid="task-checks" aria-labelledby="task-checks-title">
          {worker.checks.map(check => {
            const executedIndex = executed === null ? -1 : executed.findIndex(candidate => candidate.command === check.command)
            return (
              <li key={check.id} data-check-id={check.id}>
                <code>{check.command}</code>
                <span className="projects-muted"> · {check.id} · {check.kind} · timeout {formatDuration(check.timeout_seconds)}</span>
                {check.scenarios.length > 0 && (
                  <span className="projects-muted"> · {check.scenarios.length} {check.scenarios.length === 1 ? 'scenario' : 'scenarios'}: {check.scenarios.map(scenario => scenario.id).join(', ')}</span>
                )}
                <div className="task-check-status">
                  {executed === null ? (
                    <span className="projects-muted">{result.status === 'loading' ? 'Loading the published result to compare…' : 'No published result to compare against.'}</span>
                  ) : executedIndex === -1 ? (
                    <span className="projects-muted">not executed in this result</span>
                  ) : (
                    <a href={`#check-${executedIndex}`} onClick={event => jumpToCheck(event, `check-${executedIndex}`)}>
                      executed as check {executedIndex + 1}: exit {executed[executedIndex].exit_code}
                    </a>
                  )}
                </div>
              </li>
            )
          })}
        </ul>
      )}

      {worker.prompt === null ? (
        <p className="projects-muted" data-testid="task-prompt-none">The exact prompt was not recorded for this run (it predates prompt capture).</p>
      ) : (
        <details className="task-prompt" data-testid="task-prompt">
          <summary>Exact prompt the session received{worker.prompt.truncated ? ' (truncated by the viewer API)' : ''}</summary>
          <pre className="task-source">{worker.prompt.text}</pre>
        </details>
      )}
    </section>
  )
}

export function LaunchReceipt({ launch }: { launch: RunInputWorker['launch'] }) {
  return (
    <section className="evidence-section" aria-labelledby="launch-receipt-title" data-testid="launch-receipt">
      <h4 id="launch-receipt-title">Launch receipt</h4>
      {launch === null ? (
        <p className="projects-muted" data-testid="launch-none">No launch receipt recorded.</p>
      ) : (
        <dl className="projects-facts">
          <div><dt>Session</dt><dd>{launch.session_id === null ? 'Not yet reported by the launcher' : <code>{launch.session_id}</code>}</dd></div>
          <div><dt>Launch requested</dt><dd>{formatTime(launch.launch_requested_at)}</dd></div>
          <div><dt>Native start</dt><dd>{launch.native_started_at === null ? 'Not reported' : formatTime(launch.native_started_at)}</dd></div>
          <div><dt>Observed state</dt><dd>{launch.observed_state ?? 'Not observed'}</dd></div>
          <div><dt>Launcher status</dt><dd><code>{launch.status}</code></dd></div>
          <div><dt>Launcher invocations</dt><dd>{launch.launcher_invocations}</dd></div>
        </dl>
      )}
    </section>
  )
}

function Assumptions({ items }: { items: string[] }) {
  if (items.length === 0) return <p className="projects-muted">No open assumptions.</p>
  return <ul className="evidence-list">{items.map((item, index) => <li key={index}>{item}</li>)}</ul>
}

/** The worker's own completion signal, and the accepted handoff only when it differs from it. */
export function WorkerSignals({ completion, handoff }: { completion: RunInputWorker['completion']; handoff: RunInputWorker['handoff'] }) {
  const handoffDiffers = handoff !== null && (
    completion === null || handoff.summary !== completion.summary || JSON.stringify(handoff.open_assumptions) !== JSON.stringify(completion.open_assumptions)
  )
  return (
    <>
      <section className="evidence-section" aria-labelledby="worker-completion-title" data-testid="worker-completion">
        <h4 id="worker-completion-title">Reported by the worker</h4>
        {completion === null ? (
          <p className="projects-muted">No completion signal recorded.</p>
        ) : (
          <>
            <p>
              <span className={`status-badge ${completion.status === 'completed' ? 'status-succeeded' : 'status-failed'}`} data-status={completion.status}><span>{completion.status}</span></span>
              {' '}<span className="projects-muted">as signalled by the session itself, not a verified result.</span>
            </p>
            <p className="worker-summary">{completion.summary}</p>
            <Assumptions items={completion.open_assumptions} />
          </>
        )}
      </section>
      {handoffDiffers && (
        <section className="evidence-section" aria-labelledby="worker-handoff-title" data-testid="worker-handoff">
          <h4 id="worker-handoff-title">Handoff as accepted</h4>
          <p className="projects-muted">The accepted handoff differs from what the worker reported.</p>
          <p className="worker-summary">{handoff.summary}</p>
          <Assumptions items={handoff.open_assumptions} />
        </section>
      )}
    </>
  )
}

export function StopLine({ stop }: { stop: RunInputWorker['stop'] }) {
  const confirmed = stop !== null && stop.stopped && stop.confirmed_at !== null
  return (
    <p className="worker-stop" data-testid="worker-stop">
      {confirmed
        ? `Stop confirmed at ${formatTime(stop.confirmed_at!)}.`
        : stop === null ? 'Stop not confirmed: no stop receipt was recorded.' : 'Stop not confirmed: the stop receipt records no confirmation.'}
    </p>
  )
}
import { useMemo, type KeyboardEvent } from 'react'
import { DAG_NODE_HEIGHT, DAG_NODE_WIDTH, layoutDag } from './dag.ts'
import { KIND_LABEL, STATUS_LABEL, type NodeKind, type RunStatus } from './status.ts'
import { wrapLabel } from '../graph/labels.ts'

export type GraphNodeView = {
  node_id: string
  label: string
  kind: NodeKind
  depends_on: string[]
  /** Absent for a definition without a run (current workflow definition). */
  status?: RunStatus
  attempt?: number
}

type Props = {
  /** Identifies what the picture shows, e.g. "Pinned definition of run-001". */
  title: string
  nodes: GraphNodeView[]
  selectedId: string | null
  /** When omitted, the graph is a static picture of a definition. */
  onSelect?: (nodeId: string) => void
}

/**
 * Layered SVG rendering of a workflow definition, optionally coloured by a run's node statuses. Every node
 * is a keyboard-focusable control describing its label, kind, status and attempt; the surrounding node
 * list is the equivalent non-graphical view.
 */
export function WorkflowGraph({ title, nodes, selectedId, onSelect }: Props) {
  const layout = useMemo(() => layoutDag(nodes), [nodes])
  const interactive = onSelect !== undefined

  const keyHandler = (nodeId: string, index: number) => (event: KeyboardEvent<SVGGElement>) => {
    if (!interactive) return
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      onSelect(nodeId)
      return
    }
    const delta = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : event.key === 'ArrowLeft' || event.key === 'ArrowUp' ? -1 : 0
    if (delta === 0) return
    event.preventDefault()
    const next = nodes[(index + delta + nodes.length) % nodes.length]
    const target = event.currentTarget.ownerSVGElement?.querySelector<SVGGElement>(`[data-graph-node="${CSS.escape(next.node_id)}"]`)
    target?.focus()
  }

  return (
    <div className="workflow-graph-scroll">
      <svg
        className="workflow-graph"
        role="group"
        aria-label={title}
        viewBox={`0 0 ${layout.width} ${layout.height}`}
        width={layout.width}
        height={layout.height}
        data-testid="workflow-graph"
      >
        <defs>
          <marker id="workflow-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse">
            <path d="M 0 0 L 10 5 L 0 10 z" className="workflow-edge-arrow" />
          </marker>
        </defs>
        {layout.edges.map(edge => {
          const from = layout.positions.get(edge.from)!
          const to = layout.positions.get(edge.to)!
          const x1 = from.x + DAG_NODE_WIDTH
          const y1 = from.y + DAG_NODE_HEIGHT / 2
          const x2 = to.x
          const y2 = to.y + DAG_NODE_HEIGHT / 2
          const bend = (x2 - x1) / 2
          return (
            <path
              key={`${edge.from}->${edge.to}`}
              className="workflow-edge"
              d={`M ${x1} ${y1} C ${x1 + bend} ${y1}, ${x2 - bend} ${y2}, ${x2} ${y2}`}
              markerEnd="url(#workflow-arrow)"
              data-edge-from={edge.from}
              data-edge-to={edge.to}
            />
          )
        })}
        {nodes.map((node, index) => {
          const position = layout.positions.get(node.node_id)!
          const status = node.status
          const lines = wrapLabel(node.label, 18, 2)
          const description = [
            node.label,
            KIND_LABEL[node.kind].toLowerCase(),
            status ? STATUS_LABEL[status].toLowerCase() : null,
            node.attempt !== undefined ? `attempt ${node.attempt}` : null,
          ].filter(Boolean).join(', ')
          const className = [
            'workflow-node',
            `workflow-node-${node.kind}`,
            status ? `is-${status}` : 'is-definition',
            node.node_id === selectedId ? 'is-selected' : '',
          ].filter(Boolean).join(' ')
          return (
            <g
              key={node.node_id}
              className={className}
              transform={`translate(${position.x} ${position.y})`}
              data-graph-node={node.node_id}
              data-status={status ?? 'definition'}
              role={interactive ? 'button' : undefined}
              tabIndex={interactive ? 0 : undefined}
              aria-label={description}
              aria-pressed={interactive ? node.node_id === selectedId : undefined}
              onClick={interactive ? () => onSelect(node.node_id) : undefined}
              onKeyDown={keyHandler(node.node_id, index)}
            >
              <rect className="workflow-node-shape" width={DAG_NODE_WIDTH} height={DAG_NODE_HEIGHT} rx="8" />
              <rect className="workflow-node-focus" x="-3" y="-3" width={DAG_NODE_WIDTH + 6} height={DAG_NODE_HEIGHT + 6} rx="10" />
              <rect className="workflow-node-status-bar" x="0" y="0" width="6" height={DAG_NODE_HEIGHT} rx="3" />
              <text className="workflow-node-label" x="14" y={lines.length === 1 ? 24 : 20} aria-hidden="true">
                {lines.map((line, lineIndex) => (
                  <tspan key={lineIndex} x="14" dy={lineIndex === 0 ? 0 : 14}>{line}</tspan>
                ))}
              </text>
              <text className="workflow-node-meta" x="14" y={DAG_NODE_HEIGHT - 10} aria-hidden="true">
                {status ? `${STATUS_LABEL[status]}${node.attempt !== undefined ? ` · attempt ${node.attempt}` : ''}` : KIND_LABEL[node.kind]}
              </text>
              {!interactive && <title>{description}</title>}
            </g>
          )
        })}
      </svg>
    </div>
  )
}
/**
 * Deterministic layered layout for a workflow DAG: each node sits in the column after its deepest
 * dependency, rows are assigned in definition order. Pure, so the same definition always yields the same
 * picture and tests can reason about it. Cycles are impossible here because definitions are validated first.
 */
export type DagNode = { node_id: string; depends_on: string[] }

export type DagPosition = { id: string; column: number; row: number; x: number; y: number }

export type DagLayout = {
  positions: Map<string, DagPosition>
  columns: number
  rows: number
  width: number
  height: number
  edges: { from: string; to: string }[]
}

export const DAG_NODE_WIDTH = 150
export const DAG_NODE_HEIGHT = 56
export const DAG_COLUMN_GAP = 64
export const DAG_ROW_GAP = 24
export const DAG_PADDING = 16

export function layoutDag(nodes: DagNode[]): DagLayout {
  const depth = new Map<string, number>()
  const byId = new Map(nodes.map(node => [node.node_id, node]))
  function depthOf(id: string, trail: Set<string>): number {
    const known = depth.get(id)
    if (known !== undefined) return known
    const node = byId.get(id)
    if (!node || trail.has(id)) return 0
    trail.add(id)
    const value = node.depends_on.length === 0 ? 0 : 1 + Math.max(...node.depends_on.map(parent => depthOf(parent, trail)))
    trail.delete(id)
    depth.set(id, value)
    return value
  }
  const rowsPerColumn = new Map<number, number>()
  const positions = new Map<string, DagPosition>()
  for (const node of nodes) {
    const column = depthOf(node.node_id, new Set())
    const row = rowsPerColumn.get(column) ?? 0
    rowsPerColumn.set(column, row + 1)
    positions.set(node.node_id, { id: node.node_id, column, row, x: 0, y: 0 })
  }
  const columns = rowsPerColumn.size === 0 ? 0 : Math.max(...rowsPerColumn.keys()) + 1
  const rows = rowsPerColumn.size === 0 ? 0 : Math.max(...rowsPerColumn.values())
  const height = DAG_PADDING * 2 + Math.max(rows, 1) * DAG_NODE_HEIGHT + Math.max(rows - 1, 0) * DAG_ROW_GAP
  for (const position of positions.values()) {
    const count = rowsPerColumn.get(position.column) ?? 1
    const columnHeight = count * DAG_NODE_HEIGHT + (count - 1) * DAG_ROW_GAP
    const top = (height - columnHeight) / 2
    position.x = DAG_PADDING + position.column * (DAG_NODE_WIDTH + DAG_COLUMN_GAP)
    position.y = top + position.row * (DAG_NODE_HEIGHT + DAG_ROW_GAP)
  }
  const width = DAG_PADDING * 2 + Math.max(columns, 1) * DAG_NODE_WIDTH + Math.max(columns - 1, 0) * DAG_COLUMN_GAP
  const edges: { from: string; to: string }[] = []
  for (const node of nodes) {
    for (const parent of node.depends_on) if (byId.has(parent)) edges.push({ from: parent, to: node.node_id })
  }
  return { positions, columns, rows, width, height, edges }
}
/**
 * Human wording for run and node states. The wording deliberately separates "this node finished" from
 * "this workflow is complete": only a `succeeded` run is complete, and a worker node's success only means
 * its native session launched and ended its turn.
 */
import { isBlockingFinding, type ReviewResult, type RunDetail } from './api.ts'

export type RunStatus = RunDetail['summary']['status']
export type NodeKind = RunDetail['definition']['nodes'][number]['kind']

export const STATUS_LABEL: Record<RunStatus, string> = {
  pending: 'Pending',
  running: 'Running',
  awaiting_approval: 'Awaiting approval',
  paused: 'Paused',
  succeeded: 'Succeeded',
  failed: 'Failed',
  cancelled: 'Cancelled',
}

/** What a run in this status means for the workflow as a whole. */
export const RUN_STATUS_MEANING: Record<RunStatus, string> = {
  pending: 'Nothing has started yet.',
  running: 'Work is in progress. The workflow is not complete.',
  awaiting_approval: 'Stopped at a decision that has not been made. The workflow is not complete; nothing is approved by viewing it.',
  paused: 'Paused with unresolved state (for example a session that could not be reconciled). The workflow is not complete.',
  succeeded: 'Integration was confirmed and no graph work remains.',
  failed: 'A graph step or check failed. The workflow did not complete.',
  cancelled: 'The run was cancelled before completion.',
}

/** What a node in this status means, given its kind. */
export function nodeStatusMeaning(kind: NodeKind, status: RunStatus): string {
  switch (status) {
    case 'pending': return 'Not started: no attempt has run.'
    case 'running': return kind === 'worker' ? 'The native worker session is running or its turn has not been signalled complete.' : 'In progress.'
    case 'awaiting_approval': return 'Waiting for an explicit decision recorded outside this viewer. Not complete.'
    case 'paused': return 'Paused with unresolved evidence. Not complete.'
    case 'succeeded':
      return kind === 'worker'
        ? 'The worker session launched and ended its turn. This is not workflow completion; verification, review and integration are separate nodes.'
        : kind === 'integration'
          ? 'This integration step completed.'
          : 'This step completed.'
    case 'failed': return 'This step failed. The run cannot succeed without intervention.'
    case 'cancelled': return 'This step was cancelled.'
  }
}

export const KIND_LABEL: Record<NodeKind, string> = {
  prepare: 'Preparation',
  worker: 'Worker',
  verification: 'Verification',
  review: 'Review',
  integration: 'Integration',
}

export function shortRevision(revision: string): string {
  return revision.slice(0, 12)
}

export function formatTime(iso: string): string {
  const time = Date.parse(iso)
  if (Number.isNaN(time)) return iso
  return new Date(time).toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC')
}

/** Compact duration for deadlines and timeouts: 14400 → "4h", 5400 → "1h30m", 45 → "45s". */
export function formatDuration(seconds: number): string {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const rest = seconds % 60
  const parts: string[] = []
  if (hours > 0) parts.push(`${hours}h`)
  if (minutes > 0) parts.push(`${minutes}m`)
  if (rest > 0 || parts.length === 0) parts.push(`${rest}s`)
  return parts.join('')
}

/** The automatic profile's deadlines as one phrase, e.g. "worker 4h · review 30m". */
export function deadlinesLabel(automatic: { worker_timeout_seconds: number; review_timeout_seconds: number }): string {
  return `worker ${formatDuration(automatic.worker_timeout_seconds)} · review ${formatDuration(automatic.review_timeout_seconds)}`
}

const DISPOSITIONS = ['open', 'resolved', 'accepted'] as const

/** One line for a recorded review: verdict, finding counts by disposition and how many block integration (unresolved P0/P1). */
export function reviewSummary(review: ReviewResult): string {
  const { verdict, findings } = review
  if (findings.length === 0) return `${verdict} with no findings`
  const counts = DISPOSITIONS
    .map(disposition => [disposition, findings.filter(finding => finding.disposition === disposition).length] as const)
    .filter(([, count]) => count > 0)
    .map(([disposition, count]) => `${count} ${disposition}`)
  const blocking = findings.filter(isBlockingFinding).length
  return `${verdict} with ${findings.length} ${findings.length === 1 ? 'finding' : 'findings'}: ${counts.join(', ')}, ${blocking === 0 ? 'none blocking' : `${blocking} blocking`}`
}

